VALUES (378018, 'tt4255304', NULL, 'The Void', 'The Void', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/2WhZAPi3vomEQdzAPIYTvmvWaxI.jpg', 'https://image.tmdb.org/t/p/original/oZwwwezJFlHmQGBRJDLmENXwOIt.jpg', 'In the middle of a routine patrol, officer Daniel Carter happens upon a blood-soaked figure limping down a deserted stretch of road. He rushes the young man to a nearby rural hospital staffed by a skeleton crew, only to discover that patients and personnel are transforming into something inhuman. As the horror intensifies, Carter leads the other survivors on a hellish voyage into the subterranean depths of the hospital in a desperate bid to end the nightmare before it''s too late.', NULL, NULL, 4.7115, 6.019, 0, 7.86213513513513504e+01, '2026-07-15 12:01:52', '2026-10-22 13:55:04')
