VALUES (176, 'tt0387564', NULL, 'Saw', 'Saw', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/rLNSOudrayDBo1uqXjrhxcjODIC.jpg', 'https://image.tmdb.org/t/p/original/ok4ot3YbfDYZcINXf91JUfq3maB.jpg', 'Two men wake up to find themselves shackled in a grimy, abandoned bathroom. As they struggle to comprehend their predicament, they discover a disturbing tape left behind by the sadistic mastermind known as Jigsaw. With a chilling voice and cryptic instructions, Jigsaw informs them that they must partake in a gruesome game in order to secure their freedom.', NULL, NULL, 13.9224, 7.4, 0, 3.01040740740740737e+01, '2026-07-20 04:02:06', '2026-10-22 13:55:04')
