VALUES (14534, 'tt0108002', NULL, 'Rudy', 'Rudy', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/fAbfTCRpjHe2rprXBly55KL1dL9.jpg', 'https://image.tmdb.org/t/p/original/flzoI6jEw7J0X5x2rwOMZCwZ57I.jpg', 'Rudy grew up in a steel mill town where most people ended up working, but wanted to play football at Notre Dame instead. There were only a couple of problems. His grades were a little low, his athletic skills were poor, and he was only half the size of the other players. But he had the drive and the spirit of 5 people and has set his sights upon joining the team.', NULL, NULL, 4.2765, 7.344, 0, 8.416, '2026-08-19 01:49:52', '2026-10-22 13:55:04')
